mapper.select:
SELECT S.MY_ACCT_NO as acctNo,S.CCY as ccy,C.ACCT_TYPE as acctType
FROM STL_ORDERS S,BOK_BOOKSET_CAPACCT_INFO C
WHERE S.MY_ACCT_NO = C.ACCT_NO
AND S.CCY = C.CCY
AND C.BOOKSET_ID = #{booksetIdNow}
AND EXISTS(
  SELECT * FROM TRD_PRODUCT_DEAL A,TRD_PRODUCT_DEAL B
  WHERE A.TRADE_ID = B.B_TRADE_ID
  AND S.TRADE_ID = A.TRADE_ID
  AND A.PS = #{ps}
  and B.TRADE_ID= #{tradeId}
)
